def run(_context):
    import inspect
    for n in ['add_operation','add_tool','make_tool','list_library_tools','set_geometry','set_param','set_params','list_params','generate','post','inspect','strategy_guide','faces','probe']:
        f = getattr(mb, n)
        try:
            print(n, inspect.signature(f))
        except Exception as e:
            print(n, 'sig err', e)
        d = (f.__doc__ or '').strip()
        print('   ', d[:1200].replace('\n','\n    '))
        print('---')

def run(_context):
    import json
    print(json.dumps(mb.inspect(), indent=1)[:4000])
    print("FACES")
    for f in mb.faces(0):
        print(f)

def run(_context):
    for t in mb.list_library_tools(contains="TIW"):
        print(t['index'], t['description'], t['diameter_mm'], t['corner_radius_mm'], t['flute_length_mm'])

def run(_context):
    import json
    for s in ['face','adaptive2d','pocket2d','contour2d']:
        g = mb.strategy_guide(s)
        print("=====",s, len(g))
        print(json.dumps(g, indent=0))

